    const std::string& getName() const { return name_; }
    double getCgpa() const { return cgpa_; }

    void printProfile() const {
        std::cout << "Roll: " << rollNo_ << " | Name: " << name_
                  << " | CGPA: " << cgpa_ << "\n";
    }
};

