class Time {
    int h_, m_, s_;
    void normalize() {
        int total = h_ * 3600 + m_ * 60 + s_;
        total = ((total % 86400) + 86400) % 86400; // handles 24h wrap safely
        h_ = total / 3600;
        m_ = (total % 3600) / 60;
        s_ = total % 60;
    }
public:
    Time(int h = 0, int m = 0, int s = 0) : h_(h), m_(m), s_(s) { normalize(); }
    void addSeconds(int sec) { s_ += sec; normalize(); }
    void print() const {
        std::cout << std::setfill('0') << std::setw(2) << h_ << ":"
                  << std::setw(2) << m_ << ":" << std::setw(2) << s_ << "\n";
    }
};

