#include <iostream>
#include <memory>
#include <vector>

class BankAccount {
protected:
    double balance_;
public:
    explicit BankAccount(double initial) : balance_(initial >= 0 ? initial : 0) {}
    virtual ~BankAccount() = default;

    void deposit(double amt) { if (amt > 0) balance_ += amt; }
    virtual bool withdraw(double amt) {
        if (amt <= 0 || amt > balance_) return false;
        balance_ -= amt;
        return true;
    }
    virtual void monthEnd() {}
    double balance() const { return balance_; }
};

class SavingsAccount : public BankAccount {
    double rate_;
public:
    SavingsAccount(double initial, double rate) : BankAccount(initial), rate_(rate) {}
    void monthEnd() override { balance_ += balance_ * rate_; }
};

class CheckingAccount : public BankAccount {
    double overdraftLimit_;
public:
    CheckingAccount(double initial, double limit)
        : BankAccount(initial), overdraftLimit_(limit) {}
    bool withdraw(double amt) override {
        if (amt <= 0 || amt > balance_ + overdraftLimit_) return false;
        balance_ -= amt;
        return true;
    }
};

int main() {
    std::vector<std::unique_ptr<BankAccount>> accounts;
    accounts.push_back(std::make_unique<SavingsAccount>(1000, 0.05));
    accounts.push_back(std::make_unique<CheckingAccount>(100, 500));

    accounts[1]->withdraw(300);
    for (auto& acc : accounts) acc->monthEnd();

    std::cout << "Savings: " << accounts[0]->balance()
              << " | Checking: " << accounts[1]->balance() << "\n";
}

