#include <iostream>

class Complex {
    double re_, im_;
public:
    Complex(double r = 0, double i = 0) : re_(r), im_(i) {}

    Complex& operator+=(const Complex& rhs) {
        re_ += rhs.re_;
        im_ += rhs.im_;
        return *this;
    }
    friend Complex operator+(Complex lhs, const Complex& rhs) { return lhs += rhs; }
    friend Complex operator-(const Complex& a, const Complex& b) {
        return {a.re_ - b.re_, a.im_ - b.im_};
    }
    friend Complex operator*(const Complex& a, const Complex& b) {
        return {a.re_ * b.re_ - a.im_ * b.im_, a.re_ * b.im_ + a.im_ * b.re_};
    }
    friend bool operator==(const Complex& a, const Complex& b) {
        return std::abs(a.re_ - b.re_) < 1e-9 && std::abs(a.im_ - b.im_) < 1e-9;
    }
    friend bool operator!=(const Complex& a, const Complex& b) { return !(a == b); }
    friend std::ostream& operator<<(std::ostream& os, const Complex& c) {
        os << c.re_ << (c.im_ >= 0 ? " + " : " - ") << std::abs(c.im_) << "i";
        return os;
    }
};

int main() {
    Complex a(3, 4), b(1, -2);
    std::cout << "(" << a << ") * (" << b << ") = " << (a * b) << "\n";
