class DynamicIntArray {
    std::size_t size_;
    int* data_;

public:
    explicit DynamicIntArray(std::size_t n, int initVal = 0)
        : size_(n), data_(n ? new int[n] : nullptr) {
        std::fill(data_, data_ + size_, initVal);
    }

    DynamicIntArray(const DynamicIntArray& other)
        : size_(other.size_), data_(other.size_ ? new int[other.size_] : nullptr) {
        std::copy(other.data_, other.data_ + size_, data_);
    }

    DynamicIntArray& operator=(const DynamicIntArray& rhs) {
        if (this == &rhs) return *this;
        int* fresh = rhs.size_ ? new int[rhs.size_] : nullptr;
        std::copy(rhs.data_, rhs.data_ + rhs.size_, fresh);
        delete[] data_;
        data_ = fresh;
        size_ = rhs.size_;
        return *this;
    }

    ~DynamicIntArray() { delete[] data_; }

    int& operator[](std::size_t i) { return data_[i]; }
    const int& operator[](std::size_t i) const { return data_[i]; }
    int& at(std::size_t i) {
        if (i >= size_) throw std::out_of_range("Index out of range");
        return data_[i];
    }
    std::size_t size() const { return size_; }
};

int main() {
    DynamicIntArray a(3, 10);
    DynamicIntArray b(2, 5);
    b = a;
    b[0] = 99;
    std::cout << "a[0]=" << a[0] << ", b[0]=" << b[0] << "\n";
}

