class Matrix {
    std::size_t rows_, cols_;
    std::vector<double> data_;
public:
    Matrix(std::size_t r, std::size_t c, double val = 0.0)
        : rows_(r), cols_(c), data_(r * c, val) {}

    double& operator()(std::size_t r, std::size_t c) { return data_.at(r * cols_ + c); }
    const double& operator()(std::size_t r, std::size_t c) const { return data_.at(r * cols_ + c); }

    friend Matrix operator*(const Matrix& A, const Matrix& B) {
        if (A.cols_ != B.rows_) throw std::invalid_argument("Dimension mismatch");
        Matrix C(A.rows_, B.cols_, 0.0);
        for (std::size_t i = 0; i < A.rows_; ++i)
            for (std::size_t k = 0; k < A.cols_; ++k)
                for (std::size_t j = 0; j < B.cols_; ++j)
                    C(i, j) += A(i, k) * B(k, j);
        return C;
    }

    void print() const {
        for (std::size_t i = 0; i < rows_; ++i) {
            for (std::size_t j = 0; j < cols_; ++j) std::cout << (*this)(i, j) << " ";
            std::cout << "\n";
        }
    }
};

int main() {
