class IDiscountStrategy {
public:
    virtual ~IDiscountStrategy() = default;
    virtual double apply(double price) const = 0;
};

class PercentDiscount : public IDiscountStrategy {
    double pct_;
public:
    explicit PercentDiscount(double p) : pct_(p) {}
    double apply(double price) const override { return price * (1.0 - pct_ / 100.0); }
};

class FlatDiscount : public IDiscountStrategy {
    double off_;
public:
    explicit FlatDiscount(double off) : off_(off) {}
    double apply(double price) const override { return std::max(0.0, price - off_); }
};

class ShoppingCart {
    double subtotal_ = 0;
    std::unique_ptr<IDiscountStrategy> strategy_;
public:
    explicit ShoppingCart(std::unique_ptr<IDiscountStrategy> s) : strategy_(std::move(s)) {}
    void addItem(double price) { subtotal_ += price; }
    void setStrategy(std::unique_ptr<IDiscountStrategy> s) { strategy_ = std::move(s); }
    double checkoutTotal() const { return strategy_ ? strategy_->apply(subtotal_) : subtotal_; }
};

