#include <stdexcept>

class Fraction {
    int num_, den_;
    void reduce() {
        if (den_ == 0) throw std::invalid_argument("Denominator cannot be zero");
        if (den_ < 0) { num_ = -num_; den_ = -den_; }
        int g = std::gcd(num_ < 0 ? -num_ : num_, den_);
        num_ /= g;
        den_ /= g;
    }
public:
    Fraction(int n = 0, int d = 1) : num_(n), den_(d) { reduce(); }

    friend Fraction operator+(const Fraction& a, const Fraction& b) {
        return Fraction(a.num_ * b.den_ + b.num_ * a.den_, a.den_ * b.den_);
    }
    friend bool operator==(const Fraction& a, const Fraction& b) {
        return a.num_ == b.num_ && a.den_ == b.den_;
    }
    friend bool operator<(const Fraction& a, const Fraction& b) {
        return static_cast<long long>(a.num_) * b.den_ <
               static_cast<long long>(b.num_) * a.den_;
    }
    friend std::ostream& operator<<(std::ostream& os, const Fraction& f) {
        return os << f.num_ << "/" << f.den_;
    }
};

int main() {
    Fraction a(2, 4), b(1, 3), c(2, 3);
    std::cout << a << " + " << b << " = " << (a + b)
              << " | " << a << " < " << c << ": " << (a < c) << "\n";
