#include <cstddef>
#include <iostream>
#include <utility>
#include <vector>

class Buffer {
    std::size_t size_;
    int* data_;
public:
    explicit Buffer(std::size_t n = 0)
        : size_(n), data_(n ? new int[n]() : nullptr) {}

    ~Buffer() { delete[] data_; }

    Buffer(const Buffer& other)
        : size_(other.size_), data_(other.size_ ? new int[other.size_] : nullptr) {
        std::copy(other.data_, other.data_ + size_, data_);
        std::cout << "CopyCtor\n";
    }

    Buffer& operator=(const Buffer& rhs) {
        if (this == &rhs) return *this;
        int* fresh = rhs.size_ ? new int[rhs.size_] : nullptr;
        std::copy(rhs.data_, rhs.data_ + rhs.size_, fresh);
        delete[] data_;
        data_ = fresh;
        size_ = rhs.size_;
        std::cout << "CopyAssign\n";
        return *this;
    }

    Buffer(Buffer&& other) noexcept : size_(other.size_), data_(other.data_) {
        other.size_ = 0;
        other.data_ = nullptr;
        std::cout << "MoveCtor\n";
    }

    Buffer& operator=(Buffer&& rhs) noexcept {
        if (this == &rhs) return *this;
        delete[] data_;
        data_ = rhs.data_;
        size_ = rhs.size_;
        rhs.data_ = nullptr;
        rhs.size_ = 0;
        std::cout << "MoveAssign\n";
        return *this;
    }

    std::size_t size() const noexcept { return size_; }
};

int main() {
    std::vector<Buffer> vec;
    vec.reserve(1);
    vec.push_back(Buffer(10)); // MoveCtor
    vec.push_back(Buffer(20)); // Reallocates: moves existing Buffer(10) via noexcept MoveCtor!
}

