class SharedInt {
    int* val_ = nullptr;
    int* count_ = nullptr;

    void release() noexcept {
        if (count_ && --(*count_) == 0) {
            delete val_;
            delete count_;
        }
        val_ = nullptr;
        count_ = nullptr;
    }

public:
    explicit SharedInt(int v) : val_(new int(v)), count_(new int(1)) {}
    SharedInt(const SharedInt& o) noexcept : val_(o.val_), count_(o.count_) {
        if (count_) ++(*count_);
    }
    SharedInt& operator=(const SharedInt& rhs) noexcept {
        if (this == &rhs) return *this;
        release();
        val_ = rhs.val_;
        count_ = rhs.count_;
        if (count_) ++(*count_);
        return *this;
    }
    SharedInt(SharedInt&& o) noexcept
        : val_(std::exchange(o.val_, nullptr)), count_(std::exchange(o.count_, nullptr)) {}
    SharedInt& operator=(SharedInt&& rhs) noexcept {
        if (this != &rhs) {
            release();
            val_ = std::exchange(rhs.val_, nullptr);
            count_ = std::exchange(rhs.count_, nullptr);
        }
        return *this;
    }
    ~SharedInt() { release(); }

    int get() const { return *val_; }
    int useCount() const { return count_ ? *count_ : 0; }
};

