        : id_(id), len_(len), bytes_(len ? new unsigned char[len] : nullptr) {
        std::fill(bytes_, bytes_ + len_, fill);
    }
    Packet(const Packet& o)
        : id_(o.id_), len_(o.len_), bytes_(o.len_ ? new unsigned char[o.len_] : nullptr) {
        std::copy(o.bytes_, o.bytes_ + len_, bytes_);
