        unsigned char* fresh = rhs.len_ ? new unsigned char[rhs.len_] : nullptr; // May throw!
        std::copy(rhs.bytes_, rhs.bytes_ + rhs.len_, fresh);
        delete[] bytes_; // Safe: nothing below can throw!
        bytes_ = fresh;
        len_ = rhs.len_;
        id_ = rhs.id_;
        return *this;
    }
    ~Packet() { delete[] bytes_; }

    int id() const { return id_; }
    std::size_t length() const { return len_; }
};

