class ICompressor {
public:
    virtual ~ICompressor() = default;
    virtual std::string compress(const std::string& data) const = 0;
};

class ZipCompressor : public ICompressor {
public:
    std::string compress(const std::string& data) const override { return "[ZIP] " + data; }
};

class GzipCompressor : public ICompressor {
public:
    std::string compress(const std::string& data) const override { return "[GZIP] " + data; }
};

class CompressorFactory {
    using Creator = std::function<std::unique_ptr<ICompressor>()>;
    inline static std::unordered_map<std::string, Creator> registry_;
public:
    static void registerType(const std::string& key, Creator creator) {
        registry_[key] = std::move(creator);
    }
    static std::unique_ptr<ICompressor> create(const std::string& key) {
        auto it = registry_.find(key);
        return it != registry_.end() ? it->second() : nullptr;
    }
};

int main() {
    CompressorFactory::registerType("zip", [] { return std::make_unique<ZipCompressor>(); });
    CompressorFactory::registerType("gzip", [] { return std::make_unique<GzipCompressor>(); });

    for (const auto& fmt : {"zip", "gzip"}) {
        if (auto c = CompressorFactory::create(fmt)) {
            std::cout << c->compress("data") << "\n";
        }
    }
}

