class IObserver {
public:
    virtual ~IObserver() = default;
    virtual void onPriceUpdate(const std::string& symbol, double price) = 0;
};

class MobileApp : public IObserver {
public:
    void onPriceUpdate(const std::string& symbol, double price) override {
        std::cout << "[MobileApp] " << symbol << " -> " << price << "\n";
    }
};

class StockTicker {
    std::vector<std::weak_ptr<IObserver>> observers_;
public:
    void subscribe(const std::shared_ptr<IObserver>& obs) { observers_.push_back(obs); }

    void setPrice(const std::string& sym, double price) {
        observers_.erase(
            std::remove_if(observers_.begin(), observers_.end(),
                [&](const std::weak_ptr<IObserver>& wp) {
                    if (auto sp = wp.lock()) {
                        sp->onPriceUpdate(sym, price);
                        return false;
                    }
                    return true; // Remove expired observer!
                }),
            observers_.end());
    }
};

int main() {
    StockTicker ticker;
    auto app = std::make_shared<MobileApp>();
    {
        auto tempApp = std::make_shared<MobileApp>();
        ticker.subscribe(app);
        ticker.subscribe(tempApp);
    } // tempApp destroyed!
    ticker.setPrice("AAPL", 195); // Only alive 'app' receives update!
}

