#include <iostream>
#include <mutex>

class ThreadSafeAccount {
    mutable std::mutex mtx_; // Mutable so const balance() can lock it!
    double balance_ = 0.0;
public:
    explicit ThreadSafeAccount(double init) : balance_(init) {}

    void deposit(double amt) {
        if (amt <= 0) return;
        std::lock_guard<std::mutex> lock(mtx_);
        balance_ += amt;
    }

    bool withdraw(double amt) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (amt <= 0 || amt > balance_) return false;
        balance_ -= amt;
        return true;
    }

    double balance() const {
        std::lock_guard<std::mutex> lock(mtx_);
        return balance_;
    }
};

int main() {
    ThreadSafeAccount acc(1000);
    acc.deposit(500);
    acc.withdraw(300);
    const ThreadSafeAccount& readView = acc;
    std::cout << "Balance: " << readView.balance() << "\n";
}

