#include <cstddef>
#include <iostream>
#include <list>
#include <optional>
#include <string>
#include <unordered_map>
#include <utility>

class IStringCache {
public:
    virtual ~IStringCache() = default;
    virtual std::optional<std::string> get(int key) = 0;
    virtual void put(int key, std::string value) = 0;
};

class LRUCache final : public IStringCache {
    std::size_t cap_;
    std::list<std::pair<int, std::string>> order_;
    using Iter = std::list<std::pair<int, std::string>>::iterator;
    std::unordered_map<int, Iter> map_;
    inline static int totalHits_ = 0;

public:
    explicit LRUCache(std::size_t cap) : cap_(cap) {}
    LRUCache(const LRUCache&) = delete;
    LRUCache& operator=(const LRUCache&) = delete;

    std::optional<std::string> get(int key) override {
        auto it = map_.find(key);
        if (it == map_.end()) return std::nullopt;
        ++totalHits_;
        order_.splice(order_.begin(), order_, it->second);
        return it->second->second;
    }

    void put(int key, std::string value) override {
        if (cap_ == 0) return;
        auto it = map_.find(key);
        if (it != map_.end()) {
            it->second->second = std::move(value);
            order_.splice(order_.begin(), order_, it->second);
            return;
        }
        if (order_.size() == cap_) {
            map_.erase(order_.back().first);
            order_.pop_back();
        }
        order_.emplace_front(key, std::move(value));
        map_[key] = order_.begin();
    }

    static int totalHits() { return totalHits_; }
};

int main() {
    LRUCache cache(2);
    IStringCache& c = cache;
    c.put(1, "Alice");
    c.put(2, "Bob");
    auto r1 = c.get(1);      // 1 moves to front (MRU)
    c.put(3, "Charlie");     // Evicts LRU key 2!
    auto r2 = c.get(2);      // Miss!
    std::cout << "Hit: " << r1.value_or("none")
              << " | Miss: " << (r2 ? *r2 : "(empty)")
              << " | TotalHits: " << LRUCache::totalHits() << "\n";
}

